import{bQ as t,aL as r,u as n,G as s}from"./chunks/framework.DaEK0KQB.js";const I=JSON.parse('{"title":"googleNotebooklm","description":"","frontmatter":{"title":"googleNotebooklm","date":"2026-04-07T10:34:09.000Z","permalink":"/pages/2f7d2f/","categories":["收藏","面试"],"tags":[null]},"headers":[],"relativePath":"收藏/面试/03.googleNotebooklm.md","filePath":"收藏/面试/03.googleNotebooklm.md","lastUpdated":1787037046000}'),l={name:"收藏/面试/03.googleNotebooklm.md"};function i(g,o,a,e,d,h){return r(),n("div",null,[...o[0]||(o[0]=[s('<h1 id="googlenotebooklm" tabindex="-1">googleNotebooklm <a class="header-anchor" href="#googlenotebooklm" aria-label="Permalink to &quot;googleNotebooklm&quot;">​</a></h1><h3 id="_1-新闻信息流广告变现平台-h5" tabindex="-1">1. 新闻信息流广告变现平台 (H5) <a class="header-anchor" href="#_1-新闻信息流广告变现平台-h5" aria-label="Permalink to &quot;1\\. 新闻信息流广告变现平台 (H5)&quot;">​</a></h3><ol><li><strong>广告混排设计</strong>：通过在信息流的数据数组中预设“插槽”逻辑，根据后台配置的间隔规则（如每 5 条新闻插 1 条广告）进行动态切片插入，确保 UI 渲染层与业务逻辑解耦 1。</li><li><strong>兜底策略实现</strong>：开发了策略配置模块，当主广告位加载超时或无填充时，系统会自动触发 onError 回调并根据优先级权重逻辑切换到备用广告源（如从 A 联盟切换到 B 联盟），保证填充率 1, 2。</li><li><strong>IntersectionObserver 优势</strong>：相比滚动监听，它是由浏览器原生提供的异步监测目标元素与视口交叉状态的 API，性能极高，不会阻塞主线程，且能精准捕获“真实曝光” 2。</li><li><strong>埋点 SDK 架构</strong>：包含初始化、事件捕获、数据格式化和异步上报四个模块。利用 navigator.sendBeacon 或图片统计方式确保用户在关闭页面时埋点也能成功上报 2。</li><li><strong>激励计时防作弊</strong>：前端利用 Page Visibility API 监听切换后台行为，配合后端进行点击行为校验和频率限制，防止恶意刷奖励 2。</li><li><strong>地域屏蔽策略</strong>：基于用户 IP 或 GPS 信息，在广告请求前通过策略模块判断该地区是否在屏蔽名单内，以满足联盟合规要求 2。</li><li><strong>基础反作弊</strong>：通过记录点击坐标位移、点击频率间隔以及非法 User-Agent 识别，过滤掉大部分模拟器或脚本产生的异常点击 2。</li><li><strong>H5 性能优化</strong>：除了按需加载，还采用了 <strong>图片懒加载</strong>、资源压缩以及利用 Webpack 进行代码分割，减少首屏 JS 执行耗时 2。</li><li><strong>技术栈选型</strong>：由于是移动端信息流，选择轻量级的 <strong>Zepto</strong> 配合 <strong>TS</strong> 能在保证开发严谨性的同时，减少基础库的体积，提升加载速度 1。</li><li><strong>合规性确保</strong>：在 UI 上严格遵循各联盟要求的“广告”标识、关闭按钮位置及反馈机制，通过代码逻辑强制校验展示规范 2。</li></ol><h3 id="_2-运营管理系统-合作商数据平台" tabindex="-1">2. 运营管理系统 &amp; 合作商数据平台 <a class="header-anchor" href="#_2-运营管理系统-合作商数据平台" aria-label="Permalink to &quot;2\\. 运营管理系统 &amp; 合作商数据平台&quot;">​</a></h3><ol><li><strong>RBAC 权限实现</strong>：设计了<strong>页面、按钮、数据</strong>三层控制。页面和按钮通过路由守卫和自定义指令控制；数据权限则通过接口请求头携带角色标识，由后端配合过滤 2。</li><li><strong>多租户隔离</strong>：在前端请求拦截器中自动注入“合作商唯一标识”，确保所有查询接口都具备租户上下文，从 UI 层面杜绝跨租户访问的可能性 2。</li><li><strong>策略模式应用</strong>：将不同的收益计算公式（如按点击、按转化、按时长）封装成独立的类，通过策略映射表动态匹配，新业务接入只需新增策略类而无需修改主流程代码 3。</li><li><strong>包体积下降 30%</strong>：通过 <strong>CDN 外链</strong> 引入 ElementUI 等重型库，配合 Vite 的 <strong>代码分割（Code Splitting）</strong> 和动态 import，将非核心资源从主包中剥离 3。</li><li><strong>Vite 配置细节</strong>：在 vite.config.ts 中配置 rollupOptions.external 将库排除，并利用 html-plugin 在模板中注入 CDN 链接 3。</li><li><strong>通用表格组件</strong>：封装了基于配置项驱动的表格，支持 schema 配置列信息、排序规则和分页参数，统一了整个平台的交互体验 3。</li><li><strong>OSS 文件处理</strong>：利用 OSS SDK 实现前端直传，通过 <strong>分片上传</strong> 优化大文件体验，并利用签名链接实现报表的高速下载 3。</li><li><strong>浮点数精度</strong>：财务核算中使用 Big.js 或将金额统一转为“分”进行整数运算，确保收益对账的绝对准确 2。</li><li><strong>Pinia 优势</strong>：Pinia 支持更好的 TS 类型推导和模块化拆分，在多租户场景下可以更清晰地维护各合作商的状态 2。</li><li><strong>交互规范推动</strong>：通过封装通用组件库并编写内部文档，配合 <strong>AI 工具（如 Cursor）</strong> 生成标准化代码，降低了团队的沟通与复现成本 1, 3。</li></ol><h3 id="_3-ai-拓客碰碰贴-微信小程序" tabindex="-1">3. AI 拓客碰碰贴 (微信小程序) <a class="header-anchor" href="#_3-ai-拓客碰碰贴-微信小程序" aria-label="Permalink to &quot;3\\. AI 拓客碰碰贴 (微信小程序)&quot;">​</a></h3><ol><li><strong>分包策略</strong>：将 AI 生成模块、商家看板、个人中心划分为独立子包，主包仅保留核心启动逻辑和公共组件，首屏加载显著提速 3。</li><li><strong>AI 调用封装层</strong>：设计了一个统一的接口协议层，屏蔽了底层文案生成与视频脚本生成的接口差异，实现了 AI 能力的高度复用 3。</li><li><strong>数据看板可视化</strong>：使用小程序适配版的图表库，通过 Canvas 绘制曝光、点击等核心指标，为商家提供直观的数据支持 3。</li><li><strong>WebSocket 应用</strong>：由于 AI 生成较慢，建立长连接后后端可主动推送“生成中 30%”、“生成成功”等状态，避免用户频繁轮询请求 4。</li><li><strong>体验补偿优化</strong>：在生成过程中加入趣味性的加载动画和进度提示，利用骨架屏减少视觉上的等待焦虑 4。</li><li><strong>资源压缩策略</strong>：在上传物料前，利用小程序原生 API 对图片和视频进行预压缩，降低流量消耗并提升上传稳定性 4。</li><li><strong>社交分享路径</strong>：利用小程序 onShareAppMessage 结合动态生成的分享参数，一键引导用户跳转社交平台，提高曝光 4。</li><li><strong>架构扩展性</strong>：采用模块化设计，当后端 AI 模型升级时，只需在调用层更换参数或端点，不影响前端 UI 展示逻辑 3。</li><li><strong>异常引导</strong>：针对 AI 敏感词过滤或生成失败，设计了明确的提示和重试机制，确保流程闭环 4。</li><li><strong>流量优化</strong>：对视频素材采用按需加载和分段读取，降低不必要的数据传输流量 4。</li></ol><h3 id="_4-ai-灵宝-微信小程序" tabindex="-1">4. AI 灵宝 (微信小程序) <a class="header-anchor" href="#_4-ai-灵宝-微信小程序" aria-label="Permalink to &quot;4\\. AI 灵宝 (微信小程序)&quot;">​</a></h3><ol><li><strong>UniApp 实践</strong>：利用 <strong>UniApp + Vue3</strong> 实现跨端代码复用，通过条件编译处理微信小程序特有的 Canvas 接口差异 4。</li><li><strong>Prompt 优化逻辑</strong>：前端维护一套关键词模板，将用户的简单描述与预设的风格词、光影词进行<strong>模板化拼接</strong>，显著提升生成质量 5。</li><li><strong>Canvas 预览实现</strong>：通过 Canvas 的 drawImage 功能将生成的 AI 图像按比例、位置叠加到衣服模版图层上，实现即时预览效果 5。</li><li><strong>高清处理流程</strong>：生成成功后，用户可选择“超清处理”，前端请求后端增强接口并实时反馈状态，最终获取适合印刷的高清原图 5。</li><li><strong>电商闭环</strong>：基于小程序支付 API 构建从创意生成到购物车、订单创建及微信支付的完整电商流程 5。</li><li><strong>内存压力处理</strong>：对于大图处理，先在前端进行缩略图展示，仅在必要环节（如 Canvas 合成）才加载原图，防止小程序闪退 5。</li><li><strong>状态实时推送</strong>：即使切换页面，WebSocket 依然在全局状态中运行，确保用户能随时收到 AI 生成结果的通知 5。</li><li><strong>通用 UI 封装</strong>：设计了通用的 AI 任务卡片、进度条和订单列表组件，确保商城与 AI 模块风格统一 4。</li><li><strong>下单转化分析</strong>：通过埋点数据发现，提供了 Canvas 实时预览功能后，用户的购买意向显著增强，下单率得到有效提升 5。</li><li><strong>技术难点解决</strong>：对接 Text-to-Image 接口时，主要挑战在于复杂参数的映射与多状态的同步，我通过构建状态机简化了该逻辑 4。</li></ol><h3 id="_5-互动式用户增长应用-快应用" tabindex="-1">5. 互动式用户增长应用 (快应用) <a class="header-anchor" href="#_5-互动式用户增长应用-快应用" aria-label="Permalink to &quot;5\\. 互动式用户增长应用 (快应用)&quot;">​</a></h3><ol><li><strong>快应用语法</strong>：核心是类似 Web 的 HTML/CSS/JS，但标签（如 div 对应 div，img 对应 image）和样式支持有差异，需注意其特有的生命周期 5。</li><li><strong>果树状态机</strong>：通过对象维护果树的“幼苗、成长期、成熟、收获”等状态，配合后端同步机制，确保用户状态不丢失 5。</li><li><strong>CSS3 动画优化</strong>：利用 transform 和 opacity 进行动画，避免触发重排（Reflow），在多动画并行场景下开启硬件加速 6。</li><li><strong>IconFont 优势</strong>：将数百个小图标合并为一个字体文件，极大减少了网络请求次数并显著缩减了包体积 6。</li><li><strong>交互性能</strong>：通过<strong>组件复用</strong>和<strong>状态局部更新</strong>，避免整个页面的全量渲染，保持 60 帧的流畅体验 6。</li><li><strong>父子组件通信</strong>：快应用通过 props 向下传递数据，通过 $emit 向上触发事件，与 Vue 的理念非常接近 6。</li><li><strong>广告插入时机</strong>：在用户完成“任务奖励”或“浇水”后的交互反馈瞬间展示插屏广告，符合用户心理预期，填充率高 5。</li><li><strong>用户留存手段</strong>：利用签到激励、任务循环和阶段性奖励（兑现现金）构建完整的激励闭环，驱动日活增长 5。</li><li><strong>性能监控</strong>：在关键生命周期打点，记录页面从 onInit 到渲染完成的耗时，针对慢页面进行专项优化 6。</li><li><strong>提现安全</strong>：前端在请求提现接口前，对金额和用户状态进行预校验，并配合全局的 Token 校验确保交易安全 5。</li></ol><h3 id="_6-猜歌乐园-快应用" tabindex="-1">6. 猜歌乐园 (快应用) <a class="header-anchor" href="#_6-猜歌乐园-快应用" aria-label="Permalink to &quot;6\\. 猜歌乐园 (快应用)&quot;">​</a></h3><ol><li><strong>厂商适配</strong>：通过环境常量判断当前厂商（华为、小米等），针对不同厂商的广告 API 差异编写适配器（Adapter） 6。</li><li><strong>广告 SDK 设计</strong>：抽象出 loadAd、showAd、onClose 等统一接口，隐藏底层不同联盟的调用细节，实现跨项目复用 6。</li><li><strong>调度规则</strong>：支持通过配置中心下发权重，前端 SDK 根据权重随机或按序选择广告联盟进行展示 6。</li><li><strong>Fallback 链路</strong>：当联盟 A 返回“无广告”时，SDK 内部立即触发联盟 B 的请求，直到找到可用资源或尝试完所有联盟，确保收益最大化 6。</li><li><strong>兼容性 Bug</strong>：例如某些厂商在销毁广告实例后仍有回调，我通过在回调中增加实例存在性校验来解决该类崩溃问题 6。</li><li><strong>埋点准确性</strong>：通过 adID 唯一标识每一笔广告请求，在曝光和点击时上报该 ID，确保后端统计 PV/UV/CTR 的准确 6, 7。</li><li><strong>IDE 局限</strong>：部分广告功能在模拟器无法运行，我通过真机远程调试和构建调试版包，结合日志上报来排查广告异常 6。</li><li><strong>填充率提升</strong>：由于接入了多家联盟并实现自动切换，广告填充率从单一渠道的 70% 提升到了 95% 以上 6。</li><li><strong>合规合规</strong>：根据各厂商最新政策，动态调整用户隐私协议弹窗和广告展示频次，确保应用不被下架 7。</li><li><strong>架构独立性</strong>：作为负责人，我采用了微内核架构思路，将广告变现与猜歌逻辑分离，方便未来快速复用至其他互动应用 6。</li></ol><p><strong>核心技巧总结：<strong>在面试回答时，尽量提及你如何使用 <strong>AI 工具（如 Cursor）</strong> 来辅助这些复杂逻辑的编写和重构 1，这会展现你极高的</strong>开发效率</strong>和<strong>对前沿工具的掌握能力</strong>。</p>',14)])])}const c=t(l,[["render",i]]);export{I as __pageData,c as default};
